/**
 * Generated by `createschema meter.PropertyMeter 'number:Text; numberOfTariffs:Integer; installationDate:DateTimeUtc; commissioningDate:DateTimeUtc; verificationDate:DateTimeUtc; nextVerificationDate:DateTimeUtc; controlReadingsDate:DateTimeUtc; sealingDate:DateTimeUtc; isAutomatic:Checkbox; organization:Relationship:Organization:CASCADE; property:Relationship:Property:CASCADE; resource:Relationship:MeterResource:CASCADE; meta:Json;'`
 */

const { throwAuthenticationError } = require('@open-condo/keystone/apolloErrorFormatter')
const { find } = require('@open-condo/keystone/schema')

const {
    canReadObjectsAsB2BAppServiceUser,
    canManageObjectsAsB2BAppServiceUser,
} = require('@condo/domains/miniapp/utils/b2bAppServiceUserAccess')
const {
    checkPermissionsInEmployedOrRelatedOrganizations,
    getEmployedOrRelatedOrganizationsByPermissions,
} = require('@condo/domains/organization/utils/accessSchema')
const { SERVICE } = require('@condo/domains/user/constants/common')

async function canReadPropertyMeters (args) {
    const { authentication: { item: user }, context } = args

    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false

    if (user.isSupport || user.isAdmin) return {}

    if (user.type === SERVICE) {
        return await canReadObjectsAsB2BAppServiceUser(args)
    }

    const permittedOrganizations = await getEmployedOrRelatedOrganizationsByPermissions(context, user, 'canReadMeters')

    return {
        organization: {
            id_in: permittedOrganizations,
        },
    }
}

function getCreateData (originalInput, isBulkRequest) {
    if (isBulkRequest) {
        const organizationIds = originalInput.map(el => el?.data?.organization?.connect?.id)

        if (organizationIds.filter(Boolean).length !== originalInput.length) return null

        const propertyAssignments = originalInput
            .map(input => ({
                propertyId: input?.data?.property?.connect?.id,
                organizationId: input?.data?.organization?.connect?.id,
            }))
            .filter(({ propertyId }) => Boolean(propertyId))

        return {
            organizationIds: [...new Set(organizationIds)],
            propertyAssignments,
        }
    }

    const organizationId = originalInput?.organization?.connect?.id
    if (!organizationId) return null

    const propertyId = originalInput?.property?.connect?.id
    return {
        organizationIds: [organizationId],
        propertyAssignments: propertyId ? [{ propertyId, organizationId }] : [],
    }
}

async function getUpdateData (itemIds, itemId, originalInput, isBulkRequest) {
    const ids = itemIds || [itemId]
    if (ids.length !== new Set(ids).size) return null

    const items = await find('PropertyMeter', {
        id_in: ids,
        deletedAt: null,
    })
    if (items.length !== ids.length || items.some(item => !item.organization)) return null

    const propertyAssignments = getUpdatePropertyAssignments(originalInput, items, isBulkRequest)

    return {
        organizationIds: [...new Set(items.map(item => item.organization))],
        propertyAssignments,
    }
}

function getUpdatePropertyAssignments (originalInput, items, isBulkRequest) {
    if (isBulkRequest) {
        return originalInput
            .map(({ id, data }) => ({
                propertyId: data?.property?.connect?.id,
                organizationId: items.find(meter => meter.id === id)?.organization,
            }))
            .filter(({ propertyId }) => Boolean(propertyId))
    }

    const propertyId = originalInput?.property?.connect?.id
    return propertyId ? [{ propertyId, organizationId: items[0]?.organization }] : []
}

async function doPropertiesBelongToMeterOrganizations (propertyAssignments) {
    if (propertyAssignments.length === 0) return true

    const properties = await find('Property', {
        id_in: propertyAssignments.map(({ propertyId }) => propertyId),
        deletedAt: null,
    })
    const propertiesById = new Map(properties.map(property => [property.id, property]))

    return propertyAssignments.every(({ propertyId, organizationId }) => {
        const property = propertiesById.get(propertyId)
        return !property || property.organization === organizationId
    })
}

async function canManagePropertyMeters (args) {
    const { authentication: { item: user }, originalInput, operation, itemId, itemIds, context } = args

    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false
    if (user.isSupport || user.isAdmin) return true

    const isBulkRequest = Array.isArray(originalInput)
    let accessData
    if (operation === 'create') {
        accessData = getCreateData(originalInput, isBulkRequest)
    } else if (operation === 'update') {
        accessData = await getUpdateData(itemIds, itemId, originalInput, isBulkRequest)
    }
    if (operation === 'create' || operation === 'update') {
        if (!accessData) return false
    }

    if (accessData && !await doPropertiesBelongToMeterOrganizations(accessData.propertyAssignments)) {
        return false
    }

    if (user.type === SERVICE) {
        return await canManageObjectsAsB2BAppServiceUser(args)
    }

    return await checkPermissionsInEmployedOrRelatedOrganizations(context, user, accessData?.organizationIds, 'canManageMeters')
}

/*
  Rules are logical functions that used for list access, and may return a boolean (meaning
  all or no items are available) or a set of filters that limit the available items.
*/
module.exports = {
    canReadPropertyMeters,
    canManagePropertyMeters,
}
